import React from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import NotificationBell from './NotificationBell';
import { IconShieldFilled, IconSun, IconMoon, IconLogout, IconBriefcaseFull, IconEye, IconLock, IconRobot, IconUsers, IconSettings, IconPeople } from '../Icons';

const IconUser = ({ color = '#0EA5E9', size = 13 }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <path d="M20 21v-2a4 4 0 00-4-4H8a4 4 0 00-4 4v2" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="7" r="4" stroke={color} strokeWidth="2.5"/>
  </svg>
);

const Navbar = () => {
  const { user, logout, darkMode, toggleDark } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const customerLinks = [
    { path: '/dashboard', label: 'Dashboard', Icon: IconBriefcaseFull },
    { path: '/give-consent', label: 'Give Consent', Icon: IconLock },
    { path: '/access-logs', label: 'Access Logs', Icon: IconEye },
    { path: '/talent-pool', label: 'Talent Pool', Icon: IconPeople },
    { path: '/chat', label: 'Ask Kiba', Icon: IconRobot },
  ];

  const staffLinks = [
    { path: '/staff', label: 'Staff Dashboard', Icon: IconUsers },
  ];

  const adminLinks = [
    { path: '/admin', label: 'Admin Dashboard', Icon: IconSettings },
  ];

  const navLinks = user?.role === 'customer' ? customerLinks
    : user?.role === 'staff' ? staffLinks
    : user?.role === 'admin' ? adminLinks : [];

  return (
    <nav style={{
      background: darkMode ? '#1E293B' : '#1E3A5F',
      padding: '0 24px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      height: '64px',
      boxShadow: '0 2px 16px rgba(0,0,0,0.15)',
      position: 'sticky',
      top: 0,
      zIndex: 100,
      flexWrap: 'wrap',
      gap: '8px'
    }}>
      <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '8px', textDecoration: 'none' }}>
        <IconShieldFilled size={26} />
        <span style={{ color: '#0EA5E9', fontWeight: 800, fontSize: '18px', letterSpacing: '-0.5px' }}>KibaliGuard</span>
      </Link>

      <div style={{ display: 'flex', alignItems: 'center', gap: '4px', flexWrap: 'wrap' }}>
        {navLinks.map(link => (
          <Link key={link.path} to={link.path} style={{
            color: location.pathname === link.path ? '#0EA5E9' : '#CBD5E1',
            textDecoration: 'none',
            fontWeight: 600,
            fontSize: '13px',
            padding: '6px 10px',
            borderRadius: '8px',
            background: location.pathname === link.path ? 'rgba(14,165,233,0.12)' : 'transparent',
            transition: 'all 0.2s',
            display: 'flex',
            alignItems: 'center',
            gap: '6px'
          }}>
            <link.Icon color={location.pathname === link.path ? '#0EA5E9' : '#94A3B8'} size={15} />
            {link.label}
          </Link>
        ))}

        {user && <NotificationBell />}

        <button
          onClick={toggleDark}
          style={{
            background: darkMode ? 'rgba(14,165,233,0.12)' : 'rgba(245,158,11,0.12)',
            border: `1.5px solid ${darkMode ? '#0EA5E9' : '#F59E0B'}`,
            borderRadius: '8px',
            padding: '6px 10px',
            cursor: 'pointer',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            transition: 'all 0.3s',
            marginLeft: '4px'
          }}
          title={darkMode ? 'Switch to light mode' : 'Switch to dark mode'}
        >
          {darkMode ? <IconSun /> : <IconMoon />}
        </button>

        {user && (
          <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginLeft: '4px' }}>
            <div style={{ background: '#1E3A5F', border: '1.5px solid #0EA5E9', borderRadius: '8px', padding: '4px 10px', display: 'flex', alignItems: 'center', gap: '6px' }}>
              <IconUser color="#0EA5E9" size={13} />
              <span style={{ color: '#0EA5E9', fontSize: '12px', fontWeight: 700, fontFamily: 'Roboto Mono, monospace' }}>
                {user.applicantId || user.fullName?.split(' ')[0]}
              </span>
            </div>
            <button
              onClick={handleLogout}
              style={{ background: 'rgba(239,68,68,0.12)', border: '1.5px solid #EF4444', color: '#EF4444', borderRadius: '8px', padding: '6px 12px', fontWeight: 600, fontSize: '13px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', gap: '6px', transition: 'all 0.2s' }}
            >
              <IconLogout size={14} />
              Logout
            </button>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
